import { Component, viewChild } from '@angular/core';

@Component({
  selector: 'app-dashboard',
  imports: [SalesChart],
  template: `
    <button (click)="chart()?.exportPng()">Export</button>
    @defer (on viewport) {
      <app-sales-chart />
    } @placeholder {
      <div class="chart-skeleton"></div>
    }
  `,
})
export class Dashboard {
  // A reference outside the block: SalesChart becomes eager
  readonly chart = viewChild(SalesChart);
}

import { Component } from '@angular/core';

@Component({
  selector: 'app-dashboard',
  imports: [SalesChart],
  template: `
    @defer (on viewport) {
      <app-sales-chart #chart />
      <button (click)="chart.exportPng()">Export</button>
    } @placeholder {
      <div class="chart-skeleton"></div>
    }
  `,
})
export class Dashboard {
  // No reference to SalesChart outside the block: it's split out
}
